-- 게임 메타데이터: 게임·분류·회사와 연결 테이블 (docs/architecture/data-model.md §4.2, §5)
-- 전제: `npm run db:setup-roles`로 app_user·catalog_writer 역할이 있고, 0000_profiles가 적용돼 있어야 한다.

CREATE EXTENSION IF NOT EXISTS pg_trgm;
--> statement-breakpoint

CREATE TYPE "game_source" AS ENUM ('igdb', 'manual');
--> statement-breakpoint

-- ===== 분류 =====

CREATE TABLE "platforms" (
	"id" smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"slug" text NOT NULL,
	"name" text NOT NULL,
	"igdb_id" integer,
	CONSTRAINT "platforms_slug_unique" UNIQUE ("slug"),
	CONSTRAINT "platforms_igdb_id_unique" UNIQUE ("igdb_id"),
	-- IGDB의 슬러그는 `ps4--1`처럼 하이픈이 겹칠 수 있다.
	CONSTRAINT "platforms_slug_format" CHECK ("slug" ~ '^[a-z0-9][a-z0-9-]{0,63}$'),
	CONSTRAINT "platforms_name_length" CHECK (char_length("name") BETWEEN 1 AND 100)
);
--> statement-breakpoint

CREATE TABLE "genres" (
	"id" smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"slug" text NOT NULL,
	"name" text NOT NULL,
	CONSTRAINT "genres_slug_unique" UNIQUE ("slug"),
	CONSTRAINT "genres_slug_format" CHECK ("slug" ~ '^[a-z0-9][a-z0-9-]{0,63}$'),
	CONSTRAINT "genres_name_length" CHECK (char_length("name") BETWEEN 1 AND 50)
);
--> statement-breakpoint

CREATE TABLE "tags" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"slug" text NOT NULL,
	"name" text NOT NULL,
	"source" "game_source" NOT NULL,
	CONSTRAINT "tags_slug_unique" UNIQUE ("slug"),
	CONSTRAINT "tags_slug_format" CHECK ("slug" ~ '^[a-z0-9][a-z0-9-]{0,63}$'),
	CONSTRAINT "tags_name_length" CHECK (char_length("name") BETWEEN 1 AND 50)
);
--> statement-breakpoint

-- ===== 회사: 게임과 별도 테이블. 개발사·퍼블리셔는 연결 테이블이 구분한다 =====

CREATE TABLE "game_companies" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"slug" text NOT NULL,
	"name" text NOT NULL,
	"name_ko" text,
	"igdb_id" integer,
	"country" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "game_companies_slug_unique" UNIQUE ("slug"),
	CONSTRAINT "game_companies_igdb_id_unique" UNIQUE ("igdb_id"),
	CONSTRAINT "game_companies_slug_format" CHECK ("slug" ~ '^[a-z0-9]([a-z0-9-]{0,118}[a-z0-9])?$'),
	CONSTRAINT "game_companies_name_length" CHECK (char_length("name") BETWEEN 1 AND 200),
	CONSTRAINT "game_companies_name_ko_length" CHECK ("name_ko" IS NULL OR char_length("name_ko") BETWEEN 1 AND 200),
	CONSTRAINT "game_companies_country_format" CHECK ("country" IS NULL OR "country" ~ '^[A-Z]{2}$')
);
--> statement-breakpoint

CREATE INDEX "game_companies_name_trgm" ON "game_companies" USING gin ("name" gin_trgm_ops);
--> statement-breakpoint

CREATE INDEX "game_companies_name_ko_trgm" ON "game_companies" USING gin ("name_ko" gin_trgm_ops);
--> statement-breakpoint

CREATE TRIGGER "game_companies_set_updated_at" BEFORE UPDATE ON "game_companies"
	FOR EACH ROW EXECUTE FUNCTION set_updated_at();
--> statement-breakpoint

-- ===== 게임 =====

CREATE TABLE "games" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"source" "game_source" NOT NULL,
	"external_id" text,
	"slug" text NOT NULL,
	"title" text NOT NULL,
	"title_ko" text,
	"summary" text,
	"release_date" date,
	"cover_url" text,
	"cover_width" integer,
	"cover_height" integer,
	"created_by" uuid REFERENCES "profiles" ("id") ON DELETE SET NULL,
	-- 평가 카운터는 평가 트리거(5단계)가 유지한다. 평균 = rating_sum / rating_count / 2 (점수는 1–10 정수)
	"rating_count" integer DEFAULT 0 NOT NULL,
	"rating_sum" integer DEFAULT 0 NOT NULL,
	"metadata_synced_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "games_slug_unique" UNIQUE ("slug"),
	-- `/games/new`(수동 등록)와 `/games/igdb-{id}`(IGDB 미리보기)는 경로가 따로 있으므로 슬러그로 쓸 수 없다.
	CONSTRAINT "games_slug_format" CHECK (
		"slug" ~ '^[a-z0-9]([a-z0-9-]{0,118}[a-z0-9])?$' AND "slug" <> 'new' AND "slug" !~ '^igdb-[0-9]+$'
	),
	-- IGDB 게임은 외부 ID가 있고 등록자가 없다. 수동 게임은 외부 ID가 없다(등록자가 탈퇴하면 created_by는 NULL이 된다).
	CONSTRAINT "games_source_shape" CHECK (
		("source" = 'igdb' AND "external_id" IS NOT NULL AND "external_id" ~ '^[0-9]+$' AND "created_by" IS NULL)
		OR ("source" = 'manual' AND "external_id" IS NULL)
	),
	CONSTRAINT "games_title_length" CHECK (char_length("title") BETWEEN 1 AND 200),
	CONSTRAINT "games_title_ko_length" CHECK ("title_ko" IS NULL OR char_length("title_ko") BETWEEN 1 AND 200),
	CONSTRAINT "games_summary_length" CHECK ("summary" IS NULL OR char_length("summary") <= 5000),
	CONSTRAINT "games_release_date_range" CHECK ("release_date" IS NULL OR "release_date" BETWEEN DATE '1940-01-01' AND DATE '2100-12-31'),
	CONSTRAINT "games_cover_url_https" CHECK ("cover_url" IS NULL OR ("cover_url" ~ '^https://' AND char_length("cover_url") <= 2048)),
	CONSTRAINT "games_cover_size" CHECK (
		("cover_width" IS NULL AND "cover_height" IS NULL)
		OR ("cover_width" IS NOT NULL AND "cover_height" IS NOT NULL AND "cover_width" > 0 AND "cover_height" > 0)
	),
	CONSTRAINT "games_rating_counters" CHECK (
		"rating_count" >= 0 AND "rating_sum" >= "rating_count" AND "rating_sum" <= "rating_count" * 10
	)
);
--> statement-breakpoint

CREATE UNIQUE INDEX "games_source_external_id_unique" ON "games" ("source", "external_id") WHERE "external_id" IS NOT NULL;
--> statement-breakpoint

CREATE INDEX "games_title_trgm" ON "games" USING gin ("title" gin_trgm_ops);
--> statement-breakpoint

CREATE INDEX "games_title_ko_trgm" ON "games" USING gin ("title_ko" gin_trgm_ops);
--> statement-breakpoint

CREATE INDEX "games_release_date_idx" ON "games" ("release_date" DESC);
--> statement-breakpoint

-- 인기 게임(평가 수 기준) 목록과 검색 동점 정렬
CREATE INDEX "games_rating_count_idx" ON "games" ("rating_count" DESC, "id");
--> statement-breakpoint

CREATE TRIGGER "games_set_updated_at" BEFORE UPDATE ON "games"
	FOR EACH ROW EXECUTE FUNCTION set_updated_at();
--> statement-breakpoint

